const LIGHT_SWAP: Record<string, string> = {
  '#ffffff': '#18181b',
  '#7dd3fc': '#0284c7',
  '#fbbf24': '#d97706',
  '#34d399': '#059669',
  '#d946ef': '#c026d3',
};

const DARK_SWAP: Record<string, string> = Object.fromEntries(
  Object.entries(LIGHT_SWAP).map(([dark, light]) => [light, dark]),
);

/** Swaps a preset color for its light or dark page counterpart. */
export function swapCursorGridTone(color: string, light: boolean): string {
  const table = light ? LIGHT_SWAP : DARK_SWAP;
  return table[color.toLowerCase()] ?? color;
}

export const VERTEX = `#version 300 es
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}`;

export const FRAGMENT = `#version 300 es
precision highp float;
precision highp int;

uniform vec2 uResolution;
uniform vec2 uOffset;
uniform float uCellSize;
uniform sampler2D uState;
uniform ivec2 uCells;
uniform vec3 uColor;
uniform vec3 uGridColor;
uniform float uLineWidth;
uniform float uMaxOpacity;
uniform float uFillOpacity;
uniform float uGridOpacity;
uniform float uCellRadius;
uniform float uCellGap;
uniform int uGridStyle;
uniform vec2 uMouse;
uniform float uRadius;
uniform float uSpotlight;
uniform float uPresence;
uniform float uEdgeFade;
uniform float uReveal;

out vec4 outColor;

float level(vec2 cell) {
  if (cell.x < 0.0 || cell.y < 0.0 || cell.x >= float(uCells.x) || cell.y >= float(uCells.y)) return 0.0;
  float v = texelFetch(uState, ivec2(cell), 0).r;
  return v * v * (3.0 - 2.0 * v);
}

float line(float d, float width) {
  float w = max(width, 1.0);
  return clamp(w * 0.5 + 0.5 - d, 0.0, 1.0) * (width / w);
}

float roundBox(vec2 p, vec2 b, float r) {
  vec2 q = abs(p) - b + r;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

void main() {
  vec2 pos = vec2(gl_FragCoord.x, uResolution.y - gl_FragCoord.y);
  vec2 g = (pos - uOffset) / uCellSize;
  vec2 cell = floor(g);
  vec2 f = g - cell;
  vec2 edge = min(f, 1.0 - f) * uCellSize;

  float vx = line(edge.x, uLineWidth);
  float vy = line(edge.y, uLineWidth);
  if (uGridStyle == 1) {
    float dash = uCellSize / 6.0;
    vx *= step(0.5, fract((pos.y - uOffset.y) / dash + 0.25));
    vy *= step(0.5, fract((pos.x - uOffset.x) / dash + 0.25));
  } else if (uGridStyle == 2) {
    float r = max(uLineWidth * 1.25, 1.2);
    float d = length(edge);
    vx = clamp(r + 0.5 - d, 0.0, 1.0);
    vy = 0.0;
  } else if (uGridStyle == 3) {
    float arm = uCellSize * 0.1 + uLineWidth;
    vx *= step(edge.y, arm);
    vy *= step(edge.x, arm);
  }
  float mark = max(vx, vy);

  vec2 toMouse = pos - uMouse;
  float spot = exp(-dot(toMouse, toMouse) / max(uRadius * uRadius, 1.0) * 1.6) * uSpotlight * uPresence;

  vec2 center = uResolution * 0.5;
  float reach = length(center);
  float shown = smoothstep(uReveal * (reach + uCellSize * 2.0), uReveal * (reach + uCellSize * 2.0) - uCellSize * 2.0, length(pos - center));
  shown = uReveal >= 1.0 ? 1.0 : shown;

  float fade = 1.0;
  if (uEdgeFade > 0.0) {
    vec2 norm = pos / uResolution;
    vec2 a = clamp(norm / uEdgeFade, 0.0, 1.0);
    vec2 b = clamp((1.0 - norm) / uEdgeFade, 0.0, 1.0);
    vec2 sa = a * a * a * (a * (a * 6.0 - 15.0) + 10.0);
    vec2 sb = b * b * b * (b * (b * 6.0 - 15.0) + 10.0);
    fade = sa.x * sa.y * sb.x * sb.y;
  }

  float own = level(cell);
  float gridAlpha = mark * min(uGridOpacity + spot * 0.45, 1.0) * fade * shown;
  float litAlpha = 0.0;
  float fillAlpha = 0.0;

  if (uCellGap <= 0.0 && uCellRadius <= 0.0) {
    vec2 side = step(0.5, f) * 2.0 - 1.0;
    float nx = level(cell + vec2(side.x, 0.0));
    float ny = level(cell + vec2(0.0, side.y));
    float nc = level(cell + side);
    float ex = max(own, nx);
    float ey = max(own, ny);
    float joint = max(max(ex, ey), nc);
    float lit;
    if (uGridStyle == 2) lit = vx * joint;
    else if (uGridStyle == 3) lit = max(vx * (edge.y < uLineWidth ? joint : ex), vy * (edge.x < uLineWidth ? joint : ey));
    else lit = max(vx * (edge.y < uLineWidth ? joint : ex), vy * (edge.x < uLineWidth ? joint : ey));
    litAlpha = lit * uMaxOpacity;
    fillAlpha = own * uFillOpacity;
  } else if (own > 0.0) {
    vec2 local = (f - 0.5) * uCellSize;
    float halfSize = uCellSize * 0.5 - max(uCellGap, 0.0);
    float radius = min(uCellRadius, halfSize);
    float sd = roundBox(local, vec2(halfSize), radius);
    float inside = clamp(0.5 - sd, 0.0, 1.0);
    float border = line(abs(sd + uLineWidth * 0.5), uLineWidth) * inside;
    litAlpha = border * own * uMaxOpacity;
    fillAlpha = inside * own * uFillOpacity;
  }
  litAlpha *= fade;
  fillAlpha *= fade;

  float cellAlpha = clamp(max(litAlpha, fillAlpha), 0.0, 1.0);
  float alpha = cellAlpha + gridAlpha * (1.0 - cellAlpha);
  vec3 premul = uColor * cellAlpha + uGridColor * gridAlpha * (1.0 - cellAlpha);
  outColor = vec4(premul, alpha);
}`;

export { default as CursorGrid } from './CursorGrid.vue';
export type {
  CursorGridFalloff,
  CursorGridHighlight,
  CursorGridProps,
  CursorGridStyle,
} from './types';

import type { StyleValue } from 'vue';

export type CursorGridFalloff = 'linear' | 'smooth' | 'sharp';
export type CursorGridHighlight = 'area' | 'cell';
export type CursorGridStyle = 'lines' | 'dashed' | 'dots' | 'crosses';

export interface CursorGridProps {
  /** Size of each grid cell, in px. */
  cellSize?: number;
  /** Color of lit cells and pulses. Defaults to white, or near black in light mode. */
  color?: string;
  /** Color of the grid lines. Defaults to white, or near black in light mode. */
  gridColor?: string;
  /** Reach of the cursor, in px, for the lit area and the spotlight. */
  radius?: number;
  /** How quickly cells dim toward the edge of the radius. */
  falloff?: CursorGridFalloff;
  /** Light every cell within the radius, or only the cell under the cursor. */
  highlight?: CursorGridHighlight;
  /** How long a cell stays lit before it fades, in ms. */
  holdTime?: number;
  /** How long a lit cell takes to fade out, in ms. */
  fadeDuration?: number;
  /** Width of the grid lines, in px. */
  lineWidth?: number;
  /** Brightness of a fully lit cell outline. */
  maxOpacity?: number;
  /** Soft fill inside lit cells. */
  fillOpacity?: number;
  /** Opacity of the grid lines at rest. */
  gridOpacity?: number;
  /** How the grid is drawn. */
  gridStyle?: CursorGridStyle;
  /** Corner radius of lit tiles, in px. */
  cellRadius?: number;
  /** Inset of lit cells, in px. Above 0, lit cells become separate tiles. */
  cellGap?: number;
  /** How much the grid lines brighten around the cursor, 0 to 1. */
  spotlight?: number;
  /** Clicking sends a ring of lit cells out from the click. */
  clickPulse?: boolean;
  /** Speed of the click ring, in px per second. */
  pulseSpeed?: number;
  /** Lets random cells glow softly on their own, 0 to 1. */
  ambient?: number;
  /** Fades the grid out toward the edges, 0 to 0.5. */
  edgeFade?: number;
  /** Draws the grid out from the center with a pulse on mount. */
  intro?: boolean;
  /** Uses near black lines and cells by default, for light pages. */
  lightMode?: boolean;
  /** Maximum device pixel ratio, capped at 2. */
  dpr?: number;
  class?: string;
  style?: StyleValue;
}

export interface CursorGridSettings {
  cellSize: number;
  color: string;
  gridColor: string;
  radius: number;
  falloff: CursorGridFalloff;
  highlight: CursorGridHighlight;
  holdTime: number;
  fadeDuration: number;
  lineWidth: number;
  maxOpacity: number;
  fillOpacity: number;
  gridOpacity: number;
  gridStyle: number;
  cellRadius: number;
  cellGap: number;
  spotlight: number;
  clickPulse: boolean;
  pulseSpeed: number;
  ambient: number;
  edgeFade: number;
  intro: boolean;
  dpr?: number;
}

export interface CursorGridPulse {
  x: number;
  y: number;
  t0: number;
  strength: number;
}

export interface CursorGridProgram {
  program: WebGLProgram;
  uniforms: Map<string, WebGLUniformLocation | null>;
}

export type CursorGridPreset =
  | 'minimal'
  | 'cell'
  | 'tiles'
  | 'marks'
  | 'dots'
  | 'dashed'
  | 'classic';

export type CursorGridLook = Required<
  Pick<
    CursorGridProps,
    | 'color'
    | 'gridColor'
    | 'highlight'
    | 'gridStyle'
    | 'falloff'
    | 'cellSize'
    | 'radius'
    | 'holdTime'
    | 'fadeDuration'
    | 'lineWidth'
    | 'maxOpacity'
    | 'fillOpacity'
    | 'gridOpacity'
    | 'spotlight'
    | 'cellGap'
    | 'cellRadius'
    | 'pulseSpeed'
    | 'ambient'
    | 'edgeFade'
  >
>;
